/* send request -> opens the visitor's mail app (no backend needed) */
/* ==== FORM DELIVERY ====
   To get an email notification for every submission:
   1. Go to web3forms.com, enter the email address that should receive them.
   2. An access key arrives instantly — paste it between the quotes below.
   3. Re-upload this file. Leave blank and the form falls back to opening
      the visitor's own email app (mailto). */
const FORM_KEY="b26ce370-6383-473e-926e-ceb49a91e7fd";

/* ==== PORTAL LEADS ====
   Every request is also saved as a lead in the AMBS portal (portal.ambs.co.nz → Leads).
   It runs alongside the email above, so nothing changes for the visitor. */
const PORTAL_LEAD_URL="https://portal.ambs.co.nz/api/app?action=lead";
let lastPortalLead="";
function sendPortalLead(){
  try{
    const v=id=>((document.getElementById(id)||{}).value||"").trim();
    const data={
      name:v("f-name"), company:v("f-biz"), email:v("f-email"), phone:prettyPhone(v("f-phone")),
      service:"Free session request", message:v("f-msg"),
      page:location.href.split("#")[0],
      extra:{language:document.documentElement.lang||""},
      hp:v("f-website")
    };
    const body=JSON.stringify(data);
    if(body===lastPortalLead)return;          /* don't save the same request twice */
    lastPortalLead=body;
    if(navigator.sendBeacon&&navigator.sendBeacon(PORTAL_LEAD_URL,new Blob([body],{type:"text/plain"})))return;
    fetch(PORTAL_LEAD_URL,{method:"POST",mode:"no-cors",keepalive:true,headers:{"Content-Type":"text/plain"},body:body});
  }catch(e){}
}

/* ---- validation: a name, a real email, and an NZ phone number ---- */
function fieldError(id,msg){
  const el=document.getElementById(id);if(!el)return;
  el.classList.add("invalid");
  let m=el.parentElement.querySelector(".field-err");
  if(!m){m=document.createElement("p");m.className="field-err";el.parentElement.appendChild(m);}
  m.textContent=msg;
}
function clearErrors(){
  document.querySelectorAll("#book .invalid").forEach(el=>el.classList.remove("invalid"));
  document.querySelectorAll("#book .field-err").forEach(el=>el.remove());
}
function nzPhone(raw){
  /* accepts 021 234 5678, +64 21 234 5678, 0064..., with spaces, dashes or brackets */
  let d=raw.replace(/[\s()\-\.]/g,"");
  if(d.startsWith("+64"))d="0"+d.slice(3);
  else if(d.startsWith("0064"))d="0"+d.slice(4);
  else if(d.startsWith("64")&&d.length>=10)d="0"+d.slice(2);
  else if(/^[2-9]/.test(d))d="0"+d;            /* typed without the leading 0, e.g. 21 234 5678 */
  if(!/^0[0-9]{7,10}$/.test(d))return null;   /* 8 to 11 digits in 0-prefixed form */
  /* mobile prefixes and landline area codes actually issued in NZ */
  if(!/^0(2[0-9]|3|4|6|7|9|800|508)/.test(d))return null;
  /* right length for the type: landlines 03/04/06/07/09 are 9 digits, mobiles 02x 9 to 11, 0800/0508 10 or 11 */
  if(/^0[34679]/.test(d)&&d.length!==9)return null;
  if(/^02/.test(d)&&(d.length<9||d.length>11))return null;
  if(/^0(800|508)/.test(d)&&(d.length<10||d.length>11))return null;
  return d;
}
/* ---- country code picker: New Zealand first, popular countries, then A to Z ---- */
