const POPULAR=["NZ","AU","CA","CN","IN","US","GB"];
function flag(iso){return iso.replace(/./g,c=>String.fromCodePoint(127397+c.charCodeAt(0)));}
(function fillCountries(){
  const sel=document.getElementById("f-cc");if(!sel)return;
  const opt=c=>`<option value="${c.iso}" data-dial="${c.dial}">${flag(c.iso)} ${c.name} (+${c.dial})</option>`;
  const pop=POPULAR.map(i=>COUNTRIES.find(c=>c.iso===i)).filter(Boolean);
  const rest=COUNTRIES.slice().sort((a,b)=>a.name.localeCompare(b.name,"en"));
  sel.innerHTML=`<optgroup label="Frequent">${pop.map(opt).join("")}</optgroup><optgroup label="All countries (A to Z)">${rest.map(opt).join("")}</optgroup>`;
  sel.value="NZ";
  /* closed: show just the flag and code (🇳🇿 +64); open: show full country names */
  const full=()=>{for(const o of sel.options){if(o.dataset.full)o.textContent=o.dataset.full;}};
  const short=()=>{full();const o=sel.options[sel.selectedIndex];if(!o)return;o.dataset.full=o.dataset.full||o.textContent;o.textContent=flag(o.value)+" +"+o.getAttribute("data-dial");};
  for(const o of sel.options)o.dataset.full=o.textContent;
  short();
  ["mousedown","touchstart","focus","keydown"].forEach(ev=>sel.addEventListener(ev,full,{passive:true}));
  sel.addEventListener("blur",short);
  const EX={NZ:"021 234 5678",AU:"0412 345 678",CA:"416 555 0123",US:"415 555 0123",GB:"07700 900123",IN:"98765 43210",CN:"138 0013 8000"};
  const hint=()=>{const ph=document.getElementById("f-phone");if(ph)ph.placeholder=EX[sel.value]||"";};
  hint();
  sel.addEventListener("change",()=>{short();hint();clearField("f-phone");const ph=document.getElementById("f-phone");if(ph&&ph.value.trim())checkField("f-phone");});
})();
function ccDial(){const s=document.getElementById("f-cc");if(!s)return "64";const o=s.options[s.selectedIndex];return o?o.getAttribute("data-dial"):"64";}
/* international number check: returns {cc, nat} or null */
function intlPhone(raw){
  let d=String(raw||"").replace(/[\s()\-\.]/g,"");
  if(!d)return null;
  if(d.startsWith("00"))d="+"+d.slice(2);
  if(d.startsWith("+")){                       /* typed their own country code */
    const digits=d.slice(1);
    if(!/^[0-9]{7,15}$/.test(digits))return null;
    if(digits.startsWith("64")){const nz=nzPhone("+"+digits);return nz?{cc:"64",nat:nz.slice(1)}:null;}
    const dials=[...new Set(COUNTRIES.map(c=>c.dial))].sort((x,y)=>y.length-x.length);
    const cc=dials.find(dl=>digits.startsWith(dl)&&digits.length-dl.length>=5);
    return cc?{cc:cc,nat:digits.slice(cc.length)}:{cc:"",nat:digits};
  }
  const cc=ccDial();
  if(cc==="64"){const nz=nzPhone(d);return nz?{cc:"64",nat:nz.slice(1)}:null;}
  if(!/^[0-9]+$/.test(d))return null;
  if(d.startsWith(cc)&&d.length>cc.length+6)d=d.slice(cc.length);    /* country code typed again */
  if(cc!=="39"&&d.startsWith("0"))d=d.slice(1);                      /* drop the national 0 (not for Italy) */
  if(d.length<5||d.length+cc.length>15)return null;
  return {cc:cc,nat:d};
}
function phoneOK(raw){return !!intlPhone(raw);}
function prettyPhone(raw){
  const p=intlPhone(raw);if(!p)return String(raw||"").trim();
  if(p.cc==="64")return prettyNZ("0"+p.nat);
  if(!p.cc)return "+"+p.nat;
  return "+"+p.cc+" "+p.nat.replace(/(\d{3})(?=\d{3,})/g,"$1 ");
}
function telLink(raw){const p=intlPhone(raw);return p?"tel:+"+(p.cc||"")+p.nat:"";}
function ccName(){const s=document.getElementById("f-cc");const o=s&&s.options[s.selectedIndex];const c=o&&COUNTRIES.find(x=>x.iso===o.value);return c?c.name:"";}
function phoneErr(){const tpl=t("err.phonecc");return tpl&&tpl!=="err.phonecc"?tpl.replace("{country}",ccName()):t("err.phoneintl");}
function prettyNZ(raw){
  /* 02112343333 -> +64 21 1234 3333 · 091234567 -> +64 9 123 4567 */
  const d=nzPhone(raw);
  if(!d)return raw;
  const nat=d.slice(1);
  let area,rest;
  if(/^(800|508)/.test(nat)){area=nat.slice(0,3);rest=nat.slice(3);}
  else if(/^2/.test(nat)){area=nat.slice(0,2);rest=nat.slice(2);}
  else{area=nat.slice(0,1);rest=nat.slice(1);}
  const split=rest.length>=8?4:3;
  return "+64 "+area+" "+rest.slice(0,split)+" "+rest.slice(split);
}
function validateForm(){
  clearErrors();
  const v=id=>document.getElementById(id).value.trim();
  let first=null;
  if(v("f-name").length<2){fieldError("f-name",t("err.name"));first=first||"f-name";}
  const email=v("f-email");
  if(!/^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/.test(email)){fieldError("f-email",t("err.email"));first=first||"f-email";}
  const phone=v("f-phone");
  if(phone&&!phoneOK(phone)){fieldError("f-phone",phoneErr());first=first||"f-phone";}
  if(!phone){fieldError("f-phone",t("err.phonereq"));first=first||"f-phone";}
  if(first){
    const el=document.getElementById(first);
    el.scrollIntoView({behavior:"smooth",block:"center"});
    setTimeout(()=>el.focus({preventScroll:true}),300);
    return false;
  }
  return true;
}
/* check each field as the visitor finishes with it, not only on send */
function clearField(id){
  const el=document.getElementById(id);if(!el)return;
  el.classList.remove("invalid");
  const m=el.parentElement.querySelector(".field-err");if(m)m.remove();
}
function checkField(id){
  const el=document.getElementById(id);if(!el)return true;
  const val=el.value.trim();
  clearField(id);
  if(!val)return true;                       /* silence while still empty */
  if(id==="f-name"&&val.length<2){fieldError(id,t("err.name"));return false;}
  if(id==="f-email"&&!/^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/.test(val)){fieldError(id,t("err.email"));return false;}
  if(id==="f-phone"&&!phoneOK(val)){fieldError(id,phoneErr());return false;}
  return true;
}
["f-name","f-email","f-phone"].forEach(id=>{
  const el=document.getElementById(id);if(!el)return;
  /* leaving the field, or pressing Enter, triggers the check */
  el.addEventListener("blur",()=>checkField(id));
  el.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();checkField(id);}});
  /* typing clears the warning; for email it re-checks live once it looks complete */
  el.addEventListener("input",()=>{
    clearField(id);
    if(id==="f-email"){
      const val=el.value.trim();
      if(val.includes("@")&&val.includes(".")&&val.length>6&&
         !/^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/.test(val)) fieldError(id,t("err.email"));
    }
  });
});

document.getElementById("sendbtn").addEventListener("click",async()=>{
  if(!validateForm())return;
  sendPortalLead();
  const v=id=>document.getElementById(id).value.trim();
  const subject="Free session request — "+(v("f-biz")||v("f-name")||"website");
  const body=[
    `${t("form.name")}: ${v("f-name")}`,
    `${t("form.biz")}: ${v("f-biz")}`,
    `${t("form.email")}: ${v("f-email")}`,
    `${t("form.phone")}: ${prettyPhone(v("f-phone"))}`,
    `Language: ${document.documentElement.lang}`,
    "",
    `${t("form.msg")}`,
    v("f-msg")
  ].join("\n");
  const btn=document.getElementById("sendbtn");
  if(FORM_KEY){
    btn.disabled=true;const orig=btn.textContent;btn.textContent="…";
    try{
      const tl=telLink(v("f-phone"));
      const phoneOut=tl
        ? prettyPhone(v("f-phone"))+"   (typed: "+v("f-phone")+")   tap: "+tl
        : v("f-phone");
      const r=await fetch("https://api.web3forms.com/submit",{
        method:"POST",
        headers:{"Content-Type":"application/json",Accept:"application/json"},
        body:JSON.stringify({access_key:FORM_KEY,subject:subject,
          name:v("f-name"),business:v("f-biz"),email:v("f-email"),
          phone:phoneOut,language:document.documentElement.lang,
          message:v("f-msg"),page:location.href})
      });
      const d=await r.json();
      if(d&&d.success){
        /* first name only, tidied: "peter WILLIAMS" -> "Peter" */
        const first=(v("f-name").split(/\s+/)[0]||"").replace(/[^\p{L}\p{M}'\-]/gu,"");
        const nice=first?first.charAt(0).toLocaleUpperCase()+first.slice(1).toLocaleLowerCase():"";
        btn.textContent=nice?t("form.okname").replace("{name}",nice):t("form.ok");
        btn.classList.remove("btn--sun");btn.classList.add("btn--fill");
        ["f-name","f-biz","f-email","f-phone","f-msg"].forEach(id=>{
          const el=document.getElementById(id);if(el)el.value="";
        });
        clearErrors();
        return;
      }
      throw new Error("send failed");
    }catch(e){
      btn.disabled=false;btn.textContent=orig;
      alert(t("form.err"));
    }
    return;
  }
  alert(t("form.err"));  /* no email yet — set FORM_KEY to enable delivery */
});

/* scroll reveal */
if("IntersectionObserver" in window && !reduced){
  const io=new IntersectionObserver(es=>es.forEach(e=>{
    if(e.isIntersecting){e.target.classList.add("on");io.unobserve(e.target)}
  }),{rootMargin:"0px 0px -8% 0px",threshold:.08});
  document.querySelectorAll(".rv").forEach(el=>io.observe(el));
}else{
  document.querySelectorAll(".rv").forEach(el=>el.classList.add("on"));
}

