    var cover=tops.map(function(t,k){if(!k)return 0;return Math.max(0,Math.min(1,1-(t-sticks[k])/heights[k-1]));});
    cards.forEach(function(c,i){
      var d=0;for(var k=i+1;k<cards.length;k++)d+=cover[k];
      d=Math.round(d*100)/100; if(d!==last[i]){last[i]=d;c.style.setProperty("--depth",d);}
    });
